SELECT scopes.* FROM  (SELECT p.namespace,p.client_id,p.preparation_id,p.origin,s.profile_channel,s.browser_instance,s.tab_id,s.frame_id,s.document_id,s.document_generation,s.chrome_start_token,s.broker_epoch,s.channel_epoch,s.scope_hash,s.login_route_sha256,s.created_at FROM (SELECT namespace,client_id,preparation_id,origin FROM credential_delivery_preparations WHERE namespace=:Namespace AND protection_state='held' UNION SELECT namespace,client_id,selection_id AS preparation_id,origin FROM credential_delivery_attempts WHERE namespace=:Namespace AND (protection_state='held' OR (dispatch_state='unknown' AND protection_state<>'retired'))) p LEFT JOIN credential_protection_scopes s ON s.namespace=p.namespace AND s.client_id=p.client_id AND s.preparation_id=p.preparation_id AND s.origin=p.origin ORDER BY p.client_id,p.preparation_id LIMIT 513
)  scopes